/*---
description: NFD agrees with Node for every code point U+020000 through U+02FFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [503441861, 3426003397, 1776843205, 29065669, 26186181, 3595053509, 1753262533, 677108165, 3840125381, 4205490629, 4220748229, 2382600645, 869106117, 145631685, 1684128197, 817178763];
const blocks = ["NFD U+020000-U+020FFF", "NFD U+021000-U+021FFF", "NFD U+022000-U+022FFF", "NFD U+023000-U+023FFF", "NFD U+024000-U+024FFF", "NFD U+025000-U+025FFF", "NFD U+026000-U+026FFF", "NFD U+027000-U+027FFF", "NFD U+028000-U+028FFF", "NFD U+029000-U+029FFF", "NFD U+02A000-U+02AFFF", "NFD U+02B000-U+02BFFF", "NFD U+02C000-U+02CFFF", "NFD U+02D000-U+02DFFF", "NFD U+02E000-U+02EFFF", "NFD U+02F000-U+02FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 131072 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
